// College writing: the tasks of the literature review and the research paper. Each of twelve small studies gives
// notes on three earlier sources and on the writer's own results; the literature review uses the sources, the
// introduction adds the question, the discussion adds the results, and the short paper uses all of them. The
// sources and studies are invented.

import type { WritingItem } from "@ga/subject-english";

/** Study holds the notes of one small study: its topic, three earlier sources, and the writer's own question and results. */
interface Study {
  readonly topic: string;
  readonly sources: string;
  readonly question: string;
  readonly results: string;
}

