const all: readonly Study[] = Object.values(studies);

const sourcesOf = (s: Study) => `Sources: ${s.sources}`;
const introOf = (s: Study) => `Your question: ${s.question}\n\n${sourcesOf(s)}`;
const discussionOf = (s: Study) => `Your question: ${s.question}\n\nYour results: ${s.results}\n\n${sourcesOf(s)}`;

/** literatureReviewModels are the model reviews, in the order of the studies. */
const literatureReviewModels: readonly string[] = [
  "Research agrees that teenagers need more sleep than they get, but it is less clear what schools can do about it. Okafor (2021) found that students who slept more than eight hours scored 11 points higher on a memory test, which suggests that lost sleep costs learning. Why teenagers sleep so little is explained by Silva (2020), whose survey of 3,000 teenagers showed that most go to bed later on weekends, a sign that their body clocks, not only their habits, keep them up. If that is right, an earlier bedtime is not a realistic fix, and the school day itself must move. Hughes and Grant (2018) show that this can work: when one district moved its start from 7:30 to 8:30, students slept 34 minutes more and attendance rose. Taken together, these studies make a strong case for later starts. Yet the evidence rests on a single district's change and on studies in one city or country at a time, and none compares schools with different start times directly. Whether later starts help students in other places remains an open question.",
  "Studies of birds in cities have shifted their attention from noise to light. Liu (2016) found that blackbirds sang earlier in the morning where street lamps were brightest, evidence that light changes birds' daily rhythms. Brandt and Moreau (2019) went further, showing that 41% of nests in bright areas failed against 18% in dark areas, and that noise mattered little once light was taken into account. Adeyemi (2021) offers the first sign that the harm can be reversed: when a park dimmed its lamps for a season, more nests succeeded. The three studies agree that light affects birds, and they move from behavior to breeding to a possible remedy. However, the evidence for a remedy is thin, since Adeyemi studied only one park for one year, and Brandt and Moreau note that bright sites were often noisy too. What is still missing is evidence from more places, separating light from the other disturbances of busy paths, such as people walking by.",
  "Researchers disagree less about whether homework works than about what kind works. Haddad (2020) found that among 120 primary schools, those setting over an hour of homework a week made no more reading progress than those setting none, which suggests that the amount of homework matters little for young children. Byrne (2017) found a link between homework and grades in secondary schools, but the link weakened above two hours a night, so even for older students more is not always better. Ortiz and Webb (2019) point to a different variable altogether: homework that involved reading with a parent was linked to more progress than worksheets. Read together, these studies suggest that earlier research may have asked the wrong question by counting minutes. Yet only Ortiz and Webb examined the kind of homework, and they did not compare it with schools' results over time. Whether the type of homework explains differences in progress between primary classes has not yet been tested directly.",
  "The effect of the minimum wage on jobs has been debated for decades, and the evidence points to modest effects with important exceptions. Carter (2015), reviewing 40 studies, found results ranging from no effect to moderate job losses, with the larger losses following larger increases. Lindqvist (2018) supports the view that moderate rises cost few jobs: after a 15% rise in one region, restaurant jobs for young workers fell only one percentage point more than in a neighboring region. Nwosu (2020) suggests why the effect on jobs may be small: after a rise, shop employers cut workers' hours rather than their jobs. This finding complicates the debate, since a worker who keeps a job but loses hours may not be better off. Most studies, however, count jobs rather than hours, and few ask employers directly how they responded. How businesses in a single city adjusted to a moderate rise, and whether they cut hours, raised prices or did nothing, remains unclear.",
  "Teenagers now find most of their news on social media, and research suggests that they judge it by who shares it. The Global Media Survey Group (2023) reports that 62% of people aged 13 to 24 in 15 countries get most of their news this way. Ferreira and Kim (2022) explain what this means in practice: of the 40 teenagers they observed, 31 had shared stories without opening them, and most trusted a friend's share more than the outlet that published the story. Teaching may help, but not for long; Marsh (2019) found that students taught to check other sources judged websites better, yet the effect faded within six months. These studies suggest that lessons on judging websites miss the social reason that teenagers trust a story. Yet Ferreira and Kim's evidence comes from interviews, and no study has tested whether the same headline seems more believable when a friend shares it. That experiment is the gap this study addresses.",
  "For most of the last century, King Edmund's letters were read as his own words. Hollis (1962) built her portrait of a bold king largely on them, without examining who held the pen. Mensah (2017) overturned that view, showing that the letters match the handwriting of the secretary Thomas Hale and that the king was abroad when the third was written. Mensah went on to suggest that the letters' bold policies may have been Hale's. Rourke (2020) cautions against this step: in this period secretaries usually wrote down letters that kings dictated, so handwriting shows who wrote the words on the page, not who composed them. The debate has therefore moved from who held the pen to who chose the words. Neither Mensah nor Rourke, however, examined the language of the letters themselves. A comparison of their phrasing with the king's speeches and Hale's own writings could test which man the words belong to.",
  "Whether students learn more by taking notes by hand or on a laptop is still debated. Ahmed (2018) observed that students who typed tended to copy lectures word for word, which suggests that typing may encourage recording rather than thinking. Novak (2021) supports this: in a controlled experiment, students who wrote by hand scored 7% higher on questions about ideas a week after a 20-minute lecture. Park (2023), however, found that over a semester, students who typed and then reviewed their notes weekly did as well as handwriters in earlier studies, suggesting that what students do with their notes may matter more than how they take them. These findings are not necessarily in conflict, since Novak measured a single lecture and Park a whole course with review. But no study has compared the two methods directly over a full term, the setting in which most students actually take notes, and that comparison is still needed.",
  "Whether speaking two languages protects memory in old age is less settled than early studies suggested. Tanaka (2019) found that among 2,000 adults over 65, those who used two languages daily were diagnosed with memory loss four years later than those who used one; however, the bilingual group also had more education. Rossi (2017), comparing adults with the same education, found a gap of only about one year, which suggests that education explains much of Tanaka's result. Lind (2021), reviewing the field, reports that larger and more careful studies tend to show smaller effects. The literature thus points to a real but modest advantage, smaller than the headlines that followed Tanaka's study. What remains uncertain is whether any advantage survives when education is held constant in other communities, since Rossi's is the only study to do so.",
  "Research shows that trees cool cities, and that the cooling is unevenly shared. Osei (2023) found that every 10% increase in tree cover was linked to afternoon temperatures 0.6 degrees lower, and that the poorest neighborhoods had both the fewest trees and the most pavement. Other measures cool streets less: Grant and Silva (2019) found that light-colored roofs lowered nearby street temperatures by about 0.3 degrees. The city has committed to planting 20,000 trees (City Planning Department, 2022), but its plan does not say where. Together these sources make a case for planting trees first in poorer neighborhoods. Yet both studies measure the air, while people walking and children playing also feel the heat of the ground beneath them, which none of these sources measures. How much trees cool the surfaces of a street remains to be shown.",
  "The belief that bike lanes harm shops rests largely on what shop owners think their customers do. The Main Street Traders' Association (2021) claims that 70% of customers arrive by car, but it gives no source for the figure. Hart (2018) suggests why such figures may be too high: in a survey in one city, shop owners overestimated by half the share of their customers who came by car. Duarte (2020) shows what happens to sales when lanes are built: across 500 shops, sales rose slightly faster on streets with new lanes than on similar streets without them. Together these sources suggest that fears of lost business are based on a mistaken picture of how customers travel. However, Hart's survey was in a single city, and Duarte measured sales rather than travel. No study of our town has compared how customers actually arrive with what shop owners believe.",
  "Research on minority languages suggests that they survive when they have a use outside the home. Abara (2018) found that young people in three villages saw Tolo as useful only within the family, and that this, rather than shame, led them to stop speaking it. Two studies show what can give a language a wider role. Fischer (2016) found that schools teaching some subjects in a minority language raised the number of young speakers over twenty years, and Moreno (2020) found that young people listened to minority-language radio when it played music and local news. Both remedies, however, depend on institutions, schools and radio stations, that small communities may not control. None of these studies considers the internet, where young people spend much of their time and where a community can publish for itself. Whether an online presence could give Tolo the role that Abara found missing is still unknown.",
  "There is good evidence that free breakfast helps children come to school, and some evidence that it helps them once they are there. Petrov (2022) found in a trial of 300 schools that attendance rose by 3 percentage points where breakfast was served for a year. Chang (2019) suggests why: in a study of 200 pupils, those who ate breakfast scored higher on tests of attention in the late morning. Bello (2023) adds a longer view, reporting calmer mornings over five years in 40 schools, though her evidence comes from teachers' comments rather than data. These sources agree that breakfast benefits children, but they measure attendance and attention, not the smaller daily signs of a difficult morning, such as arriving late or feeling unwell. Whether a breakfast program changes those signs in a single school has not been examined.",
];

/** introductionModels are the model introductions, in the order of the studies. */
const introductionModels: readonly string[] = [
  "Most teenagers do not get the sleep they need, and research suggests that this costs them in school. Students who sleep more than eight hours remember more of what they learn (Okafor, 2021), yet most teenagers' body clocks keep them awake late (Silva, 2020). When one district moved its start from 7:30 to 8:30, students slept 34 minutes more (Hughes & Grant, 2018). That evidence comes from a single change in a single district, however, and few studies have compared schools with different start times directly. This study asks whether the start time of a school's first class affects how much its students sleep on school nights. Comparing two schools that start almost an hour apart, I argue that a later start gives students substantially more sleep, because they go to bed at the same time whatever time school begins.",
  "Cities are bright at night, and the birds that live in them may pay for it. Light changes when city blackbirds sing (Liu, 2016), and nests in brightly lit areas fail more than twice as often as those in the dark (Brandt & Moreau, 2019). Dimming lamps in one park was followed by more successful nests (Adeyemi, 2021). Yet these findings come from a handful of cities and a single park, and lit areas are also often busy with people. This study asks whether birds in our city's parks nest less successfully near bright paths than in dark corners. Based on a spring of observation, I argue that they do, and that the city should consider dimming lights along park paths, though light and the presence of people are hard to separate.",
  "Homework for young children is a subject of strong opinions and weak evidence. Haddad (2020) found that primary schools setting over an hour a week made no more reading progress than schools setting none, and Byrne (2017) found that even for older students, more homework stops helping beyond a point. Ortiz and Webb (2019) suggest that the kind of homework may matter more than its amount, since reading with a parent was linked to more progress than worksheets. But no study has compared classes by the kind of homework they set. This study asks whether the kind of homework a primary school sets, rather than the amount, relates to pupils' progress in reading. I argue that homework built around reading aloud at home is linked to faster progress than worksheets, which suggests that schools should change what they ask of families, not only how much.",
  "Few economic questions are argued as often as whether a higher minimum wage costs jobs. A review of 40 studies found effects ranging from none to moderate losses (Carter, 2015), and moderate rises appear to cost few jobs (Lindqvist, 2018). Yet employers may respond in ways that job counts miss, such as cutting hours (Nwosu, 2020). Few studies have asked employers directly. This study asks whether shops and cafes in our city cut jobs, hours or neither after the minimum wage rose by 10% in 2022. Drawing on interviews with 25 managers, I argue that most businesses kept their staff, but that nearly half cut hours, so counting jobs alone understates the cost of a rise to the workers it is meant to help.",
  "Most young people now get their news from social media (Global Media Survey Group, 2023), and the way they judge it may have little to do with the sources that news comes from. Teenagers often share stories without opening them and say they trust friends more than outlets (Ferreira & Kim, 2022), while lessons in checking sources have effects that fade within months (Marsh, 2019). However, what teenagers say in interviews may differ from what they do. This study asks whether students at our school are more likely to believe a false headline when a friend has shared it. Through an experiment with 120 students, I argue that they are, and that media lessons should address the pull of friendship rather than only teach students to judge websites.",
  "King Edmund's letters have long shaped his reputation as a bold ruler (Hollis, 1962). Mensah (2017) showed that they are in the handwriting of his secretary, Thomas Hale, and suggested that their policies may have been Hale's too. Rourke (2020) objects that secretaries usually wrote what kings dictated, so the handwriting cannot decide who composed the letters. The question is therefore not who held the pen but whose words the letters contain, and no one has yet compared their language with either man's other writings. This study asks whether the phrases of the letters match the king's speeches or Hale's private letters. I argue that the language is largely Hale's, which strengthens Mensah's claim, though the nature of the surviving sources means the case remains strong rather than certain.",
  "Students today must choose between a pen and a laptop, and research has not settled which helps them learn. Students who type tend to copy lectures word for word (Ahmed, 2018), and in a single lecture, those who wrote by hand understood ideas better (Novak, 2021). But students who type and review their notes over a semester may do just as well (Park, 2023). No study has compared the two methods directly over a full term. This study asks whether, over a whole term, students who take notes by hand understand a course's ideas better than those who type. Comparing two sections of the same course, I argue that the advantage of handwriting is real but small, smaller than one-lecture studies suggest.",
  "As populations age, many people hope that habits such as speaking a second language can protect their memory. Early evidence was striking: bilingual adults were diagnosed with memory loss four years later than monolingual adults (Tanaka, 2019). But the bilingual adults also had more education, and when education is held equal, the gap shrinks to about a year (Rossi, 2017); more careful studies generally find smaller effects (Lind, 2021). Only one study has held education constant. This study asks whether, among older adults in our community with similar education, those who speak two languages score better on memory tests. I argue that the difference is small and may disappear once age is considered, which supports the cautious view of the recent literature.",
  "As summers grow hotter, cities are planting trees to cool their streets. Every 10% increase in tree cover has been linked to afternoon temperatures 0.6 degrees lower (Osei, 2023), a larger effect than light-colored roofs provide (Grant & Silva, 2019), and our city plans to plant 20,000 trees (City Planning Department, 2022). These studies measure the temperature of the air, however, while pedestrians also feel the heat of the ground. This study asks how much cooler the pavement in the shade of trees is than pavement in full sun on summer afternoons. Based on measurements along one street, I argue that trees cool the ground far more than they cool the air, a benefit that studies of air temperature overlook.",
  "When towns propose bike lanes, shop owners often object that removing parking will drive away customers who arrive by car. Their fears are sometimes backed by striking figures, such as the claim that 70% of customers come by car (Main Street Traders' Association, 2021), but owners tend to overestimate that share (Hart, 2018), and sales on streets with new lanes have not fallen (Duarte, 2020). No study has asked how customers of our town's main street actually travel. This study compares how shoppers travel to the main street with what shop owners believe. Based on a survey of 300 shoppers and 20 owners, I argue that most customers do not arrive by car, and that the debate over the proposed lane rests on a mistaken picture.",
  "Of the world's languages, many are spoken only by older people, and Tolo, with about 300 speakers, is one of them. Young people in its villages see it as useful only at home (Abara, 2018). Elsewhere, minority languages have gained young speakers when taught in schools (Fischer, 2016) or played on the radio (Moreno, 2020), but both depend on institutions that small communities seldom control. The internet, where a community can publish for itself, has not been studied as a way of giving such languages a place. This study asks whether young people in the Tolo villages would use the language more if it had a place online. Drawing on a survey of 45 young people, I argue that interest is strong but that weak reading skills would limit an online project unless it began with audio and music.",
  "Hungry children struggle at school, and free breakfast is one of the simplest ways to help. A trial in 300 schools found that attendance rose by 3 percentage points when breakfast was served (Petrov, 2022), and children who eat breakfast pay attention better later in the morning (Chang, 2019). Teachers report calmer mornings (Bello, 2023), but such reports are impressions rather than records. This study asks whether, after our school began serving free breakfast, late arrivals and morning visits to the nurse changed. Using the school's own records, I argue that both fell substantially, although a change in the school's bell time means the breakfast cannot be credited with the whole effect.",
];

/** discussionModels are the model discussions, in the order of the studies. */
const discussionModels: readonly string[] = [
  "Students at the later school slept about 45 minutes more on school nights, and because bedtimes were almost the same at both schools, the extra sleep came from waking later rather than from going to bed earlier. This pattern fits Silva's (2020) finding that teenagers' body clocks keep them up late, and the size of the difference is close to the 34 minutes Hughes and Grant (2018) found after a district moved its start. If students cannot easily go to bed earlier, a later start is one of the few changes that gives them more sleep. These results should be read with caution, however. The two schools differ in size and neighborhood, either of which might affect sleep, and the survey relied on what students reported. A study following one school before and after a change in start time, with sleep measured by trackers, would test the finding more directly.",
  "Nests near lit paths failed more than twice as often as nests in dark areas, 7 of 12 against 3 of 12, a pattern close to the 41% and 18% reported by Brandt and Moreau (2019). The results suggest that light harms nesting birds in our parks as it does in larger cities. They are, however, far from conclusive. With only 24 nests, a difference of four failures could arise by chance, and light was measured with a phone app that may be inaccurate. More important, lit paths also had more people walking by, so the failures might be caused by disturbance rather than light. Adeyemi's (2021) experiment in a dimmed park points to a way of separating the two: if the city dimmed the lights along some paths but not others, nest success on paths with similar numbers of walkers could be compared.",
  "Classes whose homework centered on reading aloud at home improved by 9 points over the year, against 5 points for classes given worksheets. This supports Ortiz and Webb's (2019) suggestion that the kind of homework matters, and it helps explain Haddad's (2020) finding that the amount of homework made no difference: if schools that set many minutes of worksheets are counted alongside schools that set reading, the effect of good homework may disappear in the average. The finding should not be taken as proof that reading homework causes faster progress. Teachers chose their own homework, and those who chose reading had slightly more experience, which might explain part of the difference. A trial in which classes were assigned one kind of homework or the other, with teachers' experience balanced, would show whether reading homework is truly more effective.",
  "Only 3 of the 25 businesses cut jobs after the rise, which agrees with Lindqvist's (2018) finding that moderate increases cost few jobs. But 11 cut the hours of some staff, which supports Nwosu's (2020) observation that employers adjust hours rather than jobs. This suggests that studies counting jobs alone, like most of those reviewed by Carter (2015), may understate the effect of a rise on workers, some of whom keep their jobs but earn less than they expected. Many managers also raised prices, so part of the cost was passed to customers. These conclusions rest on interviews with 25 managers who agreed to talk, a year after the rise, and those who declined may have responded differently. Payroll records from a larger sample of businesses would show how much hours fell and for whom.",
  "Students rated 48% of false headlines as believable when they appeared to come from a friend, against 31% when posted by an unknown account. This confirms in an experiment what Ferreira and Kim (2022) found in interviews: who shares a story shapes whether teenagers believe it. Because the same headlines were shown in both conditions, the difference can be credited to the sharer rather than to the stories. If friendship makes false stories more believable, lessons that teach students to judge websites, whose effects fade quickly (Marsh, 2019), may miss the main reason students are misled. The results have a clear limit, however: the friends were invented names, and real friendships are likely to have an even stronger pull. A future study could use headlines shared by students' actual classmates, with their permission, to test the effect in a more realistic setting.",
  "Of 40 unusual phrases in the royal letters, 26 appear in Hale's private letters and only 6 in the king's speeches. This supports Mensah's (2017) suggestion that the letters' language, and possibly their policies, came from Hale, and it answers Rourke's (2020) objection in part: if the king had dictated the letters, they should echo his speeches more than his secretary's writings. Two features of the sources limit this conclusion. Hale's private letters were written after the royal ones, so he may have borrowed the phrases from the letters he had copied rather than the reverse. And the king's speeches were recorded by clerks who may have smoothed his words. A comparison with any surviving letters by Hale from before he served the king would show whether these phrases were his from the start.",
  "The handwriting section scored three points higher on essay questions, while the two sections did equally well on multiple-choice questions. This pattern matches Novak's (2021) finding that handwriting helps with ideas but not facts, although the advantage here is smaller than the 7% she found in a single lecture. That is consistent with Park (2023): over a term, students in both sections had time to review their notes, which may narrow the gap. The difference is small, however, and could be explained by other differences between the sections. Students chose their own section, and the sections met at different times of day, so the handwriting group may have been more alert or more motivated. Randomly assigning students in one section to each method would show whether the small advantage is real.",
  "The bilingual adults averaged 27 out of 30 and the monolingual adults 26, a difference of one point. Because all participants had a similar level of education, this result supports Rossi's (2017) view that much of the large gap Tanaka (2019) found came from education rather than language. The small difference may also be explained by age: the bilingual adults were three years younger on average, and memory scores usually decline with age. Once age is considered, the advantage may disappear entirely, which fits Lind's (2021) conclusion that more careful studies find smaller effects. With only 50 participants from two centers, these results cannot rule out a small benefit. A larger study matching bilingual and monolingual adults by both age and education would show whether any advantage remains.",
  "Pavement in the shade of trees averaged 31 degrees against 44 degrees in full sun, a difference of 13 degrees, while the air a meter above the ground differed by only 1.5 degrees. This suggests that studies of air temperature, such as Osei's (2023), capture only part of the cooling that trees provide. For people walking, for children playing and for pets, the heat of the ground may matter as much as the heat of the air. The result also strengthens the case for trees over light-colored roofs (Grant & Silva, 2019), which cannot shade a sidewalk. Because only one street was measured, however, these figures may not hold for streets with different trees or surfaces. Measuring several streets in different neighborhoods would show whether the city's tree plan should consider ground temperatures in choosing where to plant.",
  "Only 38% of shoppers came by car, while shop owners guessed 65%. This result agrees with Hart's (2018) finding that owners overestimate the share of customers who drive by about half, and it casts doubt on figures such as the 70% claimed by the Main Street Traders' Association (2021). If most customers arrive on foot, by bus or by bicycle, a bike lane that removes some parking is unlikely to cost shops as many customers as they fear, a conclusion consistent with Duarte's (2020) finding that sales did not fall where lanes were built. However, the survey was conducted on weekdays only, and weekend shoppers, who may travel farther, could be more likely to drive. A survey that includes weekends, together with sales records after the lane is built, would give the town a fuller picture.",
  "Most young people surveyed, 33 of 45, said they would follow a Tolo page of news or music, which suggests that the problem Abara (2018) identified, that Tolo is useful only at home, could be partly answered online. The internet would offer what schools and radio give elsewhere (Fischer, 2016; Moreno, 2020) without depending on outside institutions. But only 12 had written in Tolo, and 29 said they read it slowly, so a page built on written text might lose the readers it hopes to gain. Audio and music, which Moreno found attract young listeners, may be a better start. These results must be read with care: respondents knew the teacher who conducted the survey, who supports the language, and may have given the answers they thought were expected. Tracking how many people actually follow a page would test whether stated interest turns into use.",
  "After breakfast began, late arrivals fell by about a quarter, from 412 to 305, and morning visits to the nurse fell from 96 to 71. These changes fit Petrov's (2022) finding that breakfast improves attendance and Chang's (2019) evidence that children who eat breakfast are better able to concentrate. They also give some support, from records rather than impressions, to the calmer mornings teachers described to Bello (2023). However, the school moved its bell five minutes later in the same term, which alone could reduce late arrivals, so the breakfast cannot be credited with the whole fall. The drop in nurse visits is harder to explain by the bell change and may be the clearer sign of the breakfast's effect. Comparing the following term, when the bell time stays the same, would help separate the two changes.",
];

/** paperModels are the model short papers, in the order of the studies. */
const paperModels: readonly string[] = [
  "Later Starts, Longer Sleep: Comparing Two High Schools\n\nIntroduction\n\nStudents who sleep more than eight hours remember more of what they learn (Okafor, 2021), yet most teenagers' body clocks keep them awake late (Silva, 2020). When one district moved its start from 7:30 to 8:30, students slept 34 minutes more (Hughes & Grant, 2018), but few studies compare schools directly. This study asks whether the start time of a school's first class affects how much its students sleep. I argue that a later start gives students substantially more sleep, because they go to bed at the same time regardless.\n\nMethod and Results\n\nI surveyed 180 students at two schools, one starting at 7:45 and one at 8:40. Students at the later school reported sleeping 7 hours 50 minutes on school nights on average, against 7 hours 5 minutes at the earlier school. Bedtimes were almost the same at both.\n\nDiscussion\n\nThe 45-minute difference came from waking later, not sleeping earlier, which fits Silva's account of teenage body clocks and is close to the gain Hughes and Grant reported. The schools differ in size and neighborhood, however, and sleep was self-reported, so a study of one school before and after a change, using trackers, is needed.\n\nReferences\n\nHughes, T., & Grant, M. (2018). Moving the bell: Sleep and attendance after a later start. *Journal of Adolescent Health Policy, 9*(1), 14-29.\n\nOkafor, N. (2021). Sleep and memory in adolescence. *Journal of School Health Research, 14*(2), 33-51.\n\nSilva, R. (2020). Weekend sleep and the teenage body clock. *Sleep and Youth, 6*(3), 101-117.",
  "Lights Along the Path: Nesting Success in Two City Parks\n\nIntroduction\n\nLight changes when city birds sing (Liu, 2016), and nests in bright areas fail more than twice as often as those in the dark (Brandt & Moreau, 2019). Dimming a park's lamps was followed by more successful nests (Adeyemi, 2021), but evidence from our own city is lacking. This study asks whether birds in our parks nest less successfully near lit paths. I argue that they do, though light and disturbance by people are hard to separate.\n\nMethod and Results\n\nI observed 24 nests in two parks over one spring, recording light with a phone app. Seven of the 12 nests within 20 meters of a lit path failed, against 3 of 12 in dark areas.\n\nDiscussion\n\nThe pattern matches Brandt and Moreau's findings, but with 24 nests the difference could arise by chance, and the app may be inaccurate. Lit paths also had more walkers, so disturbance may explain some failures. Dimming some paths and not others, as Adeyemi did in one park, would separate the two causes.\n\nReferences\n\nAdeyemi, F. (2021). Dimming the park: A one-season trial. *Urban Wildlife Notes, 3*, 44-52.\n\nBrandt, L., & Moreau, J. (2019). Bright nights: Artificial light and the nesting success of city birds. *Urban Ecology Quarterly, 8*(3), 201-219.\n\nLiu, W. (2016). Street lamps and the dawn song of city blackbirds. *Bird Behaviour, 21*(2), 77-90.",
  "Reading or Worksheets? Homework and Progress in Thirty Primary Classes\n\nIntroduction\n\nPrimary schools that set more homework do not make more progress in reading (Haddad, 2020), and even for older students more homework stops helping beyond a point (Byrne, 2017). The kind of homework may matter more: reading with a parent has been linked to more progress than worksheets (Ortiz & Webb, 2019). This study asks whether the kind of homework a class receives relates to its progress. I argue that reading homework is linked to faster progress.\n\nMethod and Results\n\nI compared reading scores over one year in 30 classes in one district. Classes whose homework was mainly reading aloud at home improved by 9 points; classes given mainly worksheets improved by 5.\n\nDiscussion\n\nThe result supports Ortiz and Webb and may explain Haddad's finding: averaging good and poor homework hides the effect of either. But teachers chose their homework, and reading classes had more experienced teachers. A trial assigning homework types at random would test the effect directly.\n\nReferences\n\nByrne, K. (2017). How much is enough? Homework and grades in secondary school. *School Effectiveness Review, 28*(4), 455-472.\n\nHaddad, S. (2020). Homework and reading progress in primary school. *Educational Review, 72*(5), 610-628.\n\nOrtiz, L., & Webb, H. (2019). Reading at home: Family homework and early literacy. *Literacy Today, 15*(1), 3-19.",
  "Jobs, Hours or Neither? How Local Businesses Answered a Wage Rise\n\nIntroduction\n\nA review of 40 studies found that minimum wage rises have effects on jobs ranging from none to moderate losses (Carter, 2015), and moderate rises appear to cost few jobs (Lindqvist, 2018). Employers may cut hours instead (Nwosu, 2020), a response that job counts miss. This study asks how shops and cafes in our city responded to a 10% rise in 2022. I argue that most kept their staff, but nearly half cut hours.\n\nMethod and Results\n\nI interviewed the managers of 25 shops and cafes a year after the rise. Three cut jobs, 11 cut the hours of some staff, and 11 changed neither. Most who cut hours also raised prices slightly.\n\nDiscussion\n\nFew jobs were lost, as Lindqvist found, but the cuts in hours support Nwosu's view that counting jobs understates the cost to workers. Managers who agreed to talk may differ from those who declined, and payroll records from more businesses would show how much hours fell.\n\nReferences\n\nCarter, J. (2015). Forty years of minimum wage research: A review. *Economic Perspectives, 29*(2), 120-148.\n\nLindqvist, P. (2018). Who pays for the minimum wage? *Journal of Labor Studies, 39*(1), 45-70.\n\nNwosu, A. (2020). Fewer hours, same jobs: Employers' responses to wage rises in retail. *Work and Pay, 12*(3), 233-250.",
  "Shared by a Friend: An Experiment on Believing False Headlines\n\nIntroduction\n\nMost young people get their news from social media (Global Media Survey Group, 2023). In interviews, teenagers say they trust friends more than news outlets (Ferreira & Kim, 2022), and lessons on checking sources fade within months (Marsh, 2019). This study tests whether students are more likely to believe a false headline when a friend has shared it. I argue that they are.\n\nMethod and Results\n\nI showed 120 students ten headlines, half true and half false, presented either as shared by a named friend or as posted by an unknown account. Students rated 48% of false headlines as believable when shared by a friend, against 31% from an unknown account.\n\nDiscussion\n\nBecause the same headlines appeared in both conditions, the difference reflects the sharer, confirming Ferreira and Kim's interviews. Media lessons should address the pull of friendship. The friends were invented names, so the real effect may be stronger; a study using classmates' actual shares would test this.\n\nReferences\n\nFerreira, A., & Kim, D. (2022). Shared, not read: How teenagers decide which news to trust. *Journal of Youth and Media, 5*(1), 12-30.\n\nGlobal Media Survey Group. (2023). *Young people and news 2023*.\n\nMarsh, C. (2019). Teaching students to check: The short life of a media lesson. *Media Education Research, 7*(2), 61-79.",
  "Whose Words? The Language of King Edmund's Letters\n\nIntroduction\n\nKing Edmund's letters long defined him as a bold ruler (Hollis, 1962), but they are in the hand of his secretary, Thomas Hale, who may have shaped their policies (Mensah, 2017). Because secretaries usually wrote what kings dictated, handwriting alone cannot settle the question (Rourke, 2020). This study asks whether the letters' language matches the king's speeches or Hale's own writings. I argue that it is largely Hale's.\n\nMethod and Results\n\nI compared 40 unusual phrases in the three letters with eight of the king's recorded speeches and five of Hale's private letters. Twenty-six phrases appear in Hale's letters and six in the king's speeches.\n\nDiscussion\n\nIf the king had dictated the letters, they should echo his speeches; that they echo Hale supports Mensah and answers Rourke in part. But Hale's letters were written later and may borrow from the royal ones, and clerks may have altered the speeches. Hale's earlier writings, if any survive, would decide the matter.\n\nReferences\n\nHollis, M. (1962). *Edmund the Bold: A life*. Crown Street Press.\n\nMensah, K. (2017). The secretary's hand: Rethinking the authorship of the royal letters. *Historical Journal of the North, 60*(4), 377-399.\n\nRourke, D. (2020). Dictation and authorship at the medieval court. *Medieval Studies, 44*(1), 12-35.",
  "Pen or Laptop? Note-Taking Over a Whole Term\n\nIntroduction\n\nStudents who type tend to copy lectures word for word (Ahmed, 2018), and in a single lecture, handwriters understood ideas better (Novak, 2021). Over a semester, students who typed and reviewed their notes did as well (Park, 2023). No study has compared the methods directly over a term. This study does so, and I argue that handwriting's advantage is real but small.\n\nMethod and Results\n\nI compared final exam scores in two sections of the same course, one taking notes by hand and one typing. On essay questions, the handwriting section averaged 74% and the typing section 71%; on multiple-choice questions, both averaged 80%.\n\nDiscussion\n\nThe pattern matches Novak's, with an advantage for ideas but not facts, though smaller, perhaps because review over a term narrows the gap, as Park suggests. Students chose their sections, which met at different times, so random assignment within one section is needed to confirm the result.\n\nReferences\n\nAhmed, S. (2018). Verbatim: How laptops change what students write down. *College Teaching Quarterly, 66*(2), 40-48.\n\nNovak, E. (2021). Handwritten notes and conceptual understanding. *Learning and Instruction Today, 33*, 88-104.\n\nPark, J. (2023). Typing, reviewing, remembering: A semester-long study of laptop notes. In *Proceedings of the Conference on Teaching in Higher Education* (pp. 55-63).",
  "Two Languages, Equal Schooling: Memory in Fifty Older Adults\n\nIntroduction\n\nBilingual older adults have been diagnosed with memory loss four years later than monolingual adults (Tanaka, 2019), but they also had more education. When education is equal, the gap is about a year (Rossi, 2017), and careful studies find smaller effects (Lind, 2021). This study asks whether, among adults with similar education, bilingual adults score better on memory tests. I argue that the difference is small and may reflect age.\n\nMethod and Results\n\nI tested 50 adults aged 65 to 80 at two community centers, all of whom had finished secondary school but not university. The 22 bilingual adults averaged 27 out of 30; the 28 monolingual adults averaged 26.\n\nDiscussion\n\nThe one-point gap supports Rossi's view that education explains much of Tanaka's result. The bilingual group was also three years younger, which may account for the rest. With 50 participants, a small benefit cannot be ruled out; a larger study matching age and education is needed.\n\nReferences\n\nLind, S. (2021, June 3). Does speaking two languages really protect the brain? *Mind Matters*.\n\nRossi, G. (2017). Bilingualism, education and memory in later life. *Ageing and Cognition, 9*(4), 301-318.\n\nTanaka, H. (2019). Two languages and the ageing mind. *Journal of Ageing Studies, 22*(2), 140-162.",
  "Shade on the Sidewalk: Trees and Ground Temperature on One Street\n\nIntroduction\n\nTrees cool city air, by about 0.6 degrees for every 10% of tree cover (Osei, 2023), more than light roofs do (Grant & Silva, 2019), and our city plans to plant 20,000 trees (City Planning Department, 2022). But these figures describe the air, not the ground people walk on. This study asks how much cooler shaded pavement is than pavement in full sun. I argue that trees cool the ground far more than the air.\n\nMethod and Results\n\nOn 10 July afternoons, I measured 20 points along one street with an infrared thermometer. Shaded pavement averaged 31 degrees and sunlit pavement 44 degrees; the air a meter above differed by only 1.5 degrees.\n\nDiscussion\n\nThe 13-degree difference shows a benefit that air measurements miss, and it strengthens the case for trees over roofs, which cannot shade a sidewalk. Only one street was measured, so streets in other neighborhoods should be studied before the city decides where to plant.\n\nReferences\n\nCity Planning Department. (2022). *Heat action plan 2022-2030*.\n\nGrant, P., & Silva, M. (2019). Cool roofs and the street below. *Building and Climate, 14*(2), 88-97.\n\nOsei, R. (2023). Cooling the street: Tree cover and summer heat in fourteen neighborhoods. *Journal of Urban Climate, 11*, 220-241.",
  "How Shoppers Really Arrive: Main Street and the Proposed Bike Lane\n\nIntroduction\n\nShop owners fear that bike lanes will cost them customers who drive, and some claim that 70% arrive by car (Main Street Traders' Association, 2021). Owners tend to overestimate that share (Hart, 2018), and sales have not fallen where lanes were built (Duarte, 2020). This study compares how shoppers reach our main street with what owners believe. I argue that most customers do not drive.\n\nMethod and Results\n\nI surveyed 300 shoppers on four weekdays and 20 shop owners. Of the shoppers, 38% came by car, 41% on foot, 14% by bus and 7% by bicycle. Owners guessed on average that 65% came by car.\n\nDiscussion\n\nThe gap between belief and reality matches Hart's finding and suggests that the proposed lane would cost fewer customers than owners fear, consistent with Duarte. Weekend shoppers may drive more, however, so a survey including weekends is needed.\n\nReferences\n\nDuarte, M. (2020). Bike lanes and local business. *Transport Policy Review, 17*(2), 99-118.\n\nHart, E. (2018). How do customers arrive? Shop owners' beliefs and shoppers' travel. *Journal of Transport and Retail, 5*(1), 21-35.\n\nMain Street Traders' Association. (2021). *Save our parking* [Leaflet].",
  "A Place Online? Young People and the Tolo Language\n\nIntroduction\n\nYoung people in the Tolo villages see the language as useful only at home (Abara, 2018). Elsewhere, schools (Fischer, 2016) and radio (Moreno, 2020) have given minority languages a wider role, but small communities rarely control either. This study asks whether young people would use Tolo more if it had a place online. I argue that interest is strong but that weak reading skills call for audio first.\n\nMethod and Results\n\nWith a local teacher, I surveyed 45 people aged 14 to 25. Thirty-three said they would follow a Tolo page of news or music, 12 had written in Tolo on their phones, and 29 said they read it only slowly.\n\nDiscussion\n\nOnline, Tolo could gain the role beyond the home that Abara found missing, without outside institutions. But slow readers may ignore written pages, so audio and music, which drew young listeners in Moreno's study, are a better start. Respondents knew the teacher and may have exaggerated their interest; tracking real use would test it.\n\nReferences\n\nAbara, C. (2018). *The last speakers of Tolo*. Lakeside University Press.\n\nFischer, A. (2016). Teaching in two languages: Twenty years of a minority-language school program. *Language and Education, 30*(5), 401-419.\n\nMoreno, L. (2020). Radio and the revival of minority languages. *Language Policy Journal, 19*(3), 301-322.",
  "Before the Bell: Free Breakfast, Late Arrivals and the School Nurse\n\nIntroduction\n\nFree breakfast raised attendance in a trial of 300 schools (Petrov, 2022), and children who eat breakfast concentrate better later in the morning (Chang, 2019). Teachers report calmer mornings (Bello, 2023), but these are impressions. This study asks whether late arrivals and morning visits to the nurse changed after our school began serving breakfast. I argue that both fell, though not only because of the breakfast.\n\nMethod and Results\n\nI compared school records for the term before and the term after breakfast began. Late arrivals fell from 412 to 305, and morning visits to the nurse for headaches or stomach aches fell from 96 to 71.\n\nDiscussion\n\nThe falls fit Petrov's and Chang's findings and give records to support Bello's impressions. But the bell also moved five minutes later that term, which could reduce late arrivals on its own. The fall in nurse visits is the clearer sign of the breakfast's effect; next term's records, with the bell unchanged, will help separate the two.\n\nReferences\n\nBello, A. (2023, January 20). *What we learned from five years of free breakfast*. Food in Schools.\n\nChang, Y. (2019). Breakfast and attention in the late morning. *Child Nutrition Research, 11*(3), 150-162.\n\nPetrov, I. (2022). Free breakfast and school attendance. *Journal of Education Policy, 37*(6), 812-830.",
];

/** items pairs each study with its model under a task. */
const items = (task: (s: Study) => string, source: (s: Study) => string, models: readonly string[]): readonly WritingItem[] =>
  all.map((s, i) => ({ task: task(s), source: source(s), model: models[i] ?? "" }));

/** literatureReviewBank asks for a paragraph that synthesizes three sources and ends with the gap they leave. */
export const literatureReviewBank: readonly WritingItem[] = items(
  (s) =>
    `Write a literature review paragraph on ${s.topic}: relate the three sources to one another, and end with the gap they leave. Cite each source in APA style.`,
  sourcesOf,
  literatureReviewModels,
);

/** introductionBank asks for the introduction of a research paper: context, earlier work, the gap, the question and the thesis. */
export const introductionBank: readonly WritingItem[] = items(
  (s) =>
    `Write the introduction of a short research paper on ${s.topic}: give the context and earlier work, name the gap, state your question, and end with your thesis. Cite the sources in APA style.`,
  introOf,
  introductionModels,
);

/** discussionBank asks for the discussion of a research paper: what the results mean, how they fit earlier work, and their limits. */
export const discussionBank: readonly WritingItem[] = items(
  (s) =>
    `Write the discussion section of your research paper on ${s.topic}: interpret your results, compare them with the earlier sources, admit their limits, and say what should be studied next.`,
  discussionOf,
  discussionModels,
);

/** researchPaperBank asks for a whole short research paper with a title, three sections and APA references. */
export const researchPaperBank: readonly WritingItem[] = items(
  (s) =>
    `Write a short research paper on ${s.topic}, with a title, an introduction, a section on your method and results, a discussion, and a list of references in APA style. Invent reasonable details for the references from the notes.`,
  discussionOf,
  paperModels,
);
